import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {createGardenState,stepGarden,restoreGardenState} from '../../../../src/js/garden/GardenSimulation.js';
import {GARDEN_OPENING,GARDEN_ENDING} from '../../../../src/js/garden/GardenNarrative.js';
const tick=(s,input={},frames=1)=>{for(let i=0;i<frames;i++)stepGarden(s,input,1/60);};
const press=s=>{tick(s,{advance:true});tick(s);};
let s=createGardenState();tick(s,{},12000);assert.equal(s.stage,'INTRO');assert.equal(s.story.openingIndex,0,'Espera não troca fala');assert.ok(s.story.cardAge>199);
tick(s,{advance:true},120);assert.equal(s.story.openingIndex,1,'Segurar entrada avança uma vez');tick(s);press(s);assert.equal(s.story.openingIndex,2);
let r=restoreGardenState(structuredClone(s));assert.deepEqual(r.story,s.story,'Leitura e atuação restauradas');tick(s,{skip:true});assert.equal(s.story.openingDone,false,'Cena inédita não pode ser pulada');
for(let i=2;i<GARDEN_OPENING.length;i++)press(s);assert.equal(s.story.seenOpening,true);tick(s,{},181);assert.equal(s.stage,'RUNNING');assert.equal(s.jumps,0,'Fechar cena não pula');
s=createGardenState();s.story.seenOpening=true;tick(s,{skip:true});assert.equal(s.story.openingDone,true);tick(s,{},181);assert.equal(s.stage,'RUNNING');
for(const stage of ['INTRO','RUNNING','COMPLETE']){
 const old=structuredClone(s);old.version=7;old.stage=stage;old.age=29.5;delete old.story;delete old.storyHeld;const migrated=restoreGardenState(old);assert.equal(migrated.version,8);assert.equal(migrated.player.x,old.player.x);assert.deepEqual(migrated.encounters,old.encounters);if(stage==='INTRO'){assert.equal(migrated.story.openingIndex,5);assert.equal(migrated.story.cardAge,.5);}if(stage==='RUNNING')assert.equal(migrated.story.openingDone,true);
}
s=createGardenState();s.stage='COMPLETE';tick(s,{},12000);assert.equal(s.story.endingIndex,0);for(let i=0;i<GARDEN_ENDING.length;i++)press(s);assert.equal(s.story.endingDone,true);tick(s,{},600);assert.equal(s.stage,'COMPLETE');assert.equal(s.story.endingIndex,GARDEN_ENDING.length-1);assert.ok(s.time>200,'Piquenique continua animado');
assert.throws(()=>restoreGardenState({...s,story:{...s.story,endingIndex:99}}));
for(const [file,hash] of Object.entries({'GardenLevel':'cc3c6f2f997817b9a3d137f65f55e2532d9086d77fd936f1af32b1729488723d','GardenContact':'214869273fc466679c6db73d2452fd982629d14b7a926d4822ef63012d09de73','GardenEncounters':'9ff2d9a095550333da9e46c87a25c3c368af61d463fb3f1b3440f56cb29a2e98'}))assert.equal(createHash('sha256').update(fs.readFileSync('src/js/garden/'+file+'.js')).digest('hex'),hash,'Geometria, contato e encontros preservados: '+file);
console.log('APROVADO: espera, entrada mantida, avanço único, skip somente visto, migração 7→8 sem mudar corpos/encontros, leitura restaurada, permanência animada e hashes de física/mapa.');
